SELECT DATEADD(day, 7, OrderDate) AS DueDate
FROM Sales.SalesOrderHeader;

SELECT DATEDIFF(day, OrderDate, ShipDate) AS DaysToShip
FROM Sales.SalesOrderHeader;

SELECT order_date + 7 AS due_date FROM orders;
SELECT ship_date - order_date AS days_to_ship FROM orders;

-- Months need a function, since a month isn't a fixed day count
SELECT ADD_MONTHS(order_date, 1), MONTHS_BETWEEN(ship_date, order_date)
FROM orders;

SELECT DATE_ADD(order_date, INTERVAL 7 DAY) AS due_date
FROM orders;

SELECT DATEDIFF(ship_date, order_date) AS days_to_ship
FROM orders;

SELECT order_date + INTERVAL '7 days' AS due_date
FROM orders;

SELECT AGE(ship_date, order_date) AS time_to_ship
FROM orders;
